-- ---------------------------- bookings --------------------------
-- day_rate and total are computed from the vehicle at seed time,
-- then stored, so a later price edit cannot rewrite history.
INSERT IGNORE INTO bookings
  (reference, customer_id, vehicle_id, starts_on, ends_on, status, day_rate, total)
SELECT 'BK-1041', c.id, v.id, '2026-08-26', '2026-08-30', 'Active',
       v.price,
       CASE WHEN v.listing_type = 'rental'
            THEN v.price * GREATEST(DATEDIFF('2026-08-30', '2026-08-26'), 1)
            ELSE v.price END
  FROM customers c, vehicles v
 WHERE c.full_name = 'Danielle Reyes' AND v.slug = 'tesla-model-3';

